"""Import/export heating schedules as JSON – e.g. generated by an AI.

Format (deliberately tolerant, so that LLM output fits without rework):

    {
      "routinen": [                                  # also "routines", or a list directly
        {
          "name": "Homeoffice",
          "räume": {                                 # also "rooms"
            "Wohnzimmer": {
              "Mo-Fr": [["06:30", 21], ["08:00", 20.5], ["22:00", 17]],
              "Sa-So": [{"zeit": "08:00", "temp": 21}, {"time": "23:00", "temp": "Eco"}]
            },
            "Bad": { "täglich": [["06:00", "Komfort"], ["08:00", 18]] }
          }
        }
      ]
    }

Days: Mo Di Mi Do Fr Sa So (also Mon/Tue…, Montag…, 0–6), ranges "Mo-Fr",
lists "Mo,Mi,Fr", "täglich"/"alle"/"*", "Werktage", "Wochenende".
Temperature: a number (5–30 °C) or a level Komfort/Standard/Eco/Aus.
Rooms are matched by name (upper/lower case, umlauts and
spaces do not matter). If a routine with the name already exists, only the
rooms/days named are replaced; otherwise it is created.
"""
from __future__ import annotations

import re
from typing import Any

from . import heating_model as heating

MAX_ROUTINES = 20
MAX_POINTS = 24
TEMP_MIN, TEMP_MAX = 5.0, 30.0

_DAY_WORDS = {
    0: ("mo", "mon", "montag", "monday"), 1: ("di", "tue", "dienstag", "tuesday", "tu"),
    2: ("mi", "wed", "mittwoch", "wednesday", "we"), 3: ("do", "thu", "donnerstag", "thursday", "th"),
    4: ("fr", "fri", "freitag", "friday"), 5: ("sa", "sat", "samstag", "saturday"),
    6: ("so", "sun", "sonntag", "sunday", "su"),
}
_DAY = {w: i for i, ws in _DAY_WORDS.items() for w in ws}
_GROUPS = {"täglich": range(7), "taeglich": range(7), "alle": range(7), "all": range(7), "*": range(7),
           "daily": range(7), "jeden tag": range(7), "werktage": range(5), "werktags": range(5),
           "weekdays": range(5), "wochenende": range(5, 7), "weekend": range(5, 7)}
_LEVEL_WORDS = {"komfort": "COMFORT", "comfort": "COMFORT", "standard": "ON", "normal": "ON", "on": "ON",
                "eco": "ECO", "spar": "ECO", "sparen": "ECO", "aus": "OFF", "off": "OFF", "frostschutz": "OFF"}


class ImportError_(ValueError):
    """The import file is unusable – the text is meant for the user."""
    pass


def norm(name: Any) -> str:
    """Name for comparing: lower case, umlauts written out, only letters and digits."""
    s = " ".join(str(name or "").split()).casefold()
    for a, b in (("ä", "ae"), ("ö", "oe"), ("ü", "ue"), ("ß", "ss")):
        s = s.replace(a, b)
    return re.sub(r"[^a-z0-9]", "", s)


def parse_days(spec: Any) -> list[int]:
    """Read weekdays from a value such as "Mo–Fr", "Wochenende", "Mo, Mi" or 0…6 → list of days (0 = Monday)."""
    if isinstance(spec, int) and 0 <= spec <= 6:
        return [spec]
    s = str(spec).strip().casefold()
    if s in _GROUPS:
        return list(_GROUPS[s])
    out: list[int] = []
    for part in re.split(r"[,;/ ]+|\bund\b", s):
        part = part.strip().rstrip(".")
        if not part:
            continue
        if part in _GROUPS:
            out += list(_GROUPS[part])
            continue
        m = re.fullmatch(r"([a-zäöü]+|\d)\s*[-–]\s*([a-zäöü]+|\d)", part)
        if m:
            a, b = (int(x) if x.isdigit() else _DAY.get(x) for x in m.groups())
            if a is None or b is None:
                raise ImportError_(f"Unbekannte Tage „{spec}“")
            out += list(range(a, b + 1)) if a <= b else list(range(a, 7)) + list(range(0, b + 1))
            continue
        if part.isdigit() and 0 <= int(part) <= 6:
            out.append(int(part))
        elif part in _DAY:
            out.append(_DAY[part])
        else:
            raise ImportError_(f"Unbekannter Tag „{part}“ in „{spec}“")
    return sorted(set(out))


def parse_temp(value: Any, levels: dict[str, float]) -> float:
    """Read a temperature: a number, a text such as "21,5 °C" or a level ("Komfort", "Eco"). Rounded to half degrees;
    outside the allowed range an error."""
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        t = float(value)
    else:
        s = str(value).strip().casefold().replace("°c", "").replace("°", "").replace(",", ".").strip()
        if s in _LEVEL_WORDS:
            t = float(levels.get(_LEVEL_WORDS[s], heating.DEFAULT_LEVELS[_LEVEL_WORDS[s]]))
        else:
            try:
                t = float(s)
            except ValueError:
                raise ImportError_(f"Unbekannte Temperatur „{value}“")
    t = round(t * 2) / 2
    if not TEMP_MIN <= t <= TEMP_MAX:
        raise ImportError_(f"Temperatur {t} °C außerhalb {TEMP_MIN:g}–{TEMP_MAX:g} °C")
    return t


def parse_clock(value: Any) -> str:
    """'6:30', '06:30', '0630', '6.30', '6 Uhr' -> '06:30' / '06:00'."""
    s = str(value).strip().casefold().replace("uhr", "").strip()
    m = re.fullmatch(r"(\d{1,2})(?:[:.h]?(\d{2}))?", s)
    if not m or int(m.group(1)) > 23 or int(m.group(2) or 0) > 59:
        raise ImportError_(f"Uhrzeit nicht lesbar: „{value}“")
    return f"{int(m.group(1)):02d}:{int(m.group(2) or 0):02d}"


def parse_points(raw: Any, levels: dict[str, float]) -> list[dict[str, Any]]:
    """Read the switching points of a day – as a list of pairs, as a list of objects or as {time: temperature}."""
    if isinstance(raw, dict):   # {"06:30": 21, "22:00": 17}
        raw = list(raw.items())
    if not isinstance(raw, list):
        raise ImportError_("Schaltpunkte müssen eine Liste sein")
    pts = {}
    for p in raw[:MAX_POINTS * 2]:
        if isinstance(p, dict):
            t = p.get("time", p.get("zeit", p.get("uhrzeit")))
            v = p.get("temp", p.get("temperatur", p.get("temperature", p.get("soll"))))
        elif isinstance(p, (list, tuple)) and len(p) == 2:
            t, v = p
        else:
            raise ImportError_(f"Schaltpunkt nicht lesbar: {p!r}"[:120])
        pts[parse_clock(t)] = parse_temp(v, levels)
    if len(pts) > MAX_POINTS:
        raise ImportError_(f"Höchstens {MAX_POINTS} Schaltpunkte pro Tag")
    return [{"time": k, "temp": pts[k]} for k in sorted(pts)]


def _routine_list(doc: Any) -> list[dict[str, Any]]:
    """List of the routines from an import file: {"routinen": [...]}, a bare list or a single routine."""
    if isinstance(doc, dict):
        for k in ("routinen", "routines", "heizplaene", "heizpläne", "plans"):
            if isinstance(doc.get(k), list):
                return doc[k]
        if "name" in doc:
            return [doc]
    if isinstance(doc, list):
        return doc
    raise ImportError_("Keine Routinen gefunden (erwartet: {\"routinen\": [...]})")


def plan(doc: Any, rooms: dict[str, str], existing: dict[str, str], levels: dict[str, float]) -> dict[str, Any]:
    """Check a file and map it onto ComfyOS without changing anything.
    rooms: room id -> name (rooms with heating), existing: routine key -> name."""
    by_norm = {norm(n): rid for rid, n in rooms.items()}
    ex_by_norm = {norm(n): k for k, n in existing.items()}
    routines = _routine_list(doc)
    if len(routines) > MAX_ROUTINES:
        raise ImportError_(f"Höchstens {MAX_ROUTINES} Routinen pro Datei")
    out, total_errors = [], 0
    for i, r in enumerate(routines):
        if not isinstance(r, dict):
            raise ImportError_(f"Routine {i + 1} ist kein Objekt")
        name = " ".join(str(r.get("name") or "").split())[:40]
        entry: dict[str, Any] = {"name": name or f"Routine {i + 1}", "key": ex_by_norm.get(norm(name)),
                                 "rooms": [], "unmatched": [], "errors": [], "changes": []}
        entry["action"] = "update" if entry["key"] else "create"
        raw_rooms = r.get("räume", r.get("raeume", r.get("rooms")))
        if not isinstance(raw_rooms, dict) or not raw_rooms:
            entry["errors"].append("Keine Räume angegeben")
        for rname, days in (raw_rooms or {}).items() if isinstance(raw_rooms, dict) else []:
            rid = by_norm.get(norm(rname))
            if rid is None:
                entry["unmatched"].append(str(rname)[:40])
                continue
            covered: dict[int, list] = {}
            try:
                if not isinstance(days, dict):
                    raise ImportError_("Tage müssen ein Objekt sein, z. B. {\"Mo-Fr\": [...]}")
                for spec, pts in days.items():
                    points = parse_points(pts, levels)
                    for d in parse_days(spec):
                        covered[d] = points
            except ImportError_ as exc:
                entry["errors"].append(f"{rname}: {exc}")
                continue
            entry["rooms"].append({"file": str(rname)[:40], "room_id": rid, "name": rooms[rid],
                                   "days": [heating.DAYS[d] for d in sorted(covered)]})
            entry["changes"] += [{"room": rid, "day": d, "points": p} for d, p in sorted(covered.items())]
        total_errors += len(entry["errors"])
        out.append(entry)
    return {"routines": out, "ok": total_errors == 0 and any(e["changes"] for e in out),
            "rooms": sorted(rooms.values(), key=str.casefold)}


def export(routines: list[dict[str, Any]], rooms: dict[str, str]) -> dict[str, Any]:
    """Existing schedules in the import format (room names instead of ids, days one by one)."""
    out = []
    for r in routines:
        rr = {}
        for rid, days in (r.get("schedule") or {}).items():
            name = rooms.get(rid) or rid
            rr[name] = {heating.DAYS[int(d)]: [[p["time"], p.get("temp")] for p in pts]
                        for d, pts in sorted(days.items(), key=lambda x: int(x[0])) if pts}
        out.append({"name": r.get("name"), "räume": rr})
    return {"routinen": out}
